ader">                                </div>                            <div class="box-body mx-5">                                <form class="form-horizontal" name="frmNameChangePassword" id="frmNameChangePassword" method="post">                                    <div class="alert alert-success alert-dismissable hide" id="divSuccessBasicInfoMsg" role="alert">                                        <button type="button" class="close" data-dismiss="alert" aria-label="Close">                                            <span aria-hidden="true">&times;</span>                                        </button>                                    </div>                                    <div class="col-md-3"></div>                                    <div class="col-xs-12 col-md-6 col-sm-6 col-lg-6" id="custom_form">                                        <div class="form-group">                                            <label for="inputEmail3" class="col-sm-4 control-label">Old Password</label>                                            <div class="col-sm-6">                                                <input type="password" name="frmBasicOldPwd" class="form-control" id="frmBasicOldPwd" placeholder="Old Password">                                                <span for="icon" class="field_icon">                                                <i class="fa fa-eye toggle-password_1" aria-hidden="true" onclick="togglepwd('frmBasicOldPwd','toggle-password_1')"></i>                                                </span>                                                <div class="herr" id="ErrfrmBasicOldPwd"></div>                                            </div>                                        </div>                                        <div class="form-group">                                            <label for="inputEmail3" class="col-sm-4 control-label">New Password</label>                                            <div class="col-sm-6">                                                <input type="password" name="frmBasicNewPwd" class="form-control" id="frmBasicNewPwd" placeholder="Jigme@23" onblur="validatePasswordForm(this.value,'ErrfrmBasicNewPwd','frmBasicNewPwd')">                                                <span for="icon" class="field_icon">                                                <i class="fa fa-eye toggle-password_2" aria-hidden="true" onclick="togglepwd('frmBasicNewPwd','toggle-password_2')"></i>                                                </span>                                                <div class="herr" id="ErrfrmBasicNewPwd"></div>                                            </div>                                        </div>                                        <div class="form-group">                                            <label for="inputEmail3" class="col-sm-4 control-label">Confirm Password</label>                                            <div class="col-sm-6">                                                <input type="password" name="frmBasicConfirmPwd" class="form-control" id="frmBasicConfirmPwd" placeholder="Jigme@23" disabled="true" onblur="validatePasswordForm(this.value,'ErrfrmBasicConfirmPwd','frmBasicConfirmPwd')">                                                <span for="icon" class="field_icon">                                                <i class="fa fa-eye toggle-password_3" aria-hidden="true" onclick="togglepwd('frmBasicConfirmPwd','toggle-password_3')"></i>                                                </span>                                                <div class="herr" id="ErrfrmBasicConfirmPwd"></div>                                            </div>                                        </div>                                    </div>                                    <div class="col-md-3"></div>                                </form>                            </div><!-- /.box-body -->                            <div class="box-footer nopadding">                                <div class="herr" id="ErrOldPassword"></div>                                <button type="button" class="btn btn-info pull-right" style="margin-right:330px" onclick="return fnSaveChangePassword();">Save</button>                            </div><!-- /.box-footer -->                        </div><!-- /.box -->                    </div><!-- /.col -->                </div>            </section>        </section>    </div><!-- /.content-wrapper -->    <?php $this->load->view(CNFCOMPANY . 'template/templatefooter'); ?>    <div class="control-sidebar-bg"></div></div><!-- ./wrapper --><script type="text/javascript">//for showing password on click of eye iconfunction togglepwd(id,clsname){$('.'+clsname).toggleClass("fa-eye-slash");var input = $("#"+id);input.attr('type') === 'password' ? input.attr('type','text') : input.attr('type','password');}function validatePasswordnew(password) {    // Check if password length is at least 8 characters    if (password.length < 8) {        return "Password must be at least 8 characters long.";    }    // Check if password contains at least one special character    const specialCharacters = /[!@#$%^&*()_+[\]{};':"\\|,.<>/?]+/;    if (!specialCharacters.test(password)) {        return "Password must contain at least one special character.";    }    // Check if password contains at least one alphanumeric character    const alphanumericCharacters = /[a-zA-Z0-9]+/;    if (!alphanumericCharacters.test(password)) {        return "Password must contain at least one alphanumeric character.";    }    // Check if password contains at least one alphabetic character    const alphabeticCharacters = /[a-zA-Z]+/;    if (!alphabeticCharacters.test(password)) {        return "Password must contain at least one alphabetic character.";    }    // Check if password contains at least one numeric character    const numericCharacters = /[0-9]+/;    if (!numericCharacters.test(password)) {        return "Password must contain at least one numeric character.";    }    return "Password is valid.";}// Example usageconst userPasswords = "P@sswd2rd";const validationMessages = validatePasswordnew(userPasswords);console.log(validationMessages);function validatePassword(password,errid,field_id) {     if(password.length>0){       let msg="";    const alphabeticCharacters = /[a-zA-Z]+/;  // Check if password contains at least one alphabetic character    const specialCharacters = /[!@#$%^&*()_+[\]{};':"\\|,.<>/?]+/; // Check if password contains at least one special character    const numericCharacters = /[0-9]+/; // Check if password contains at least one numeric character    // const alphanumericCharacters = /[a-zA-Z0-9]+/; // Check if password contains at least one alphanumeric character        if (!alphabeticCharacters.test(password)) {        msg= "Password must contain at least one alphabetic character.";    }else if (!specialCharacters.test(password)) {        msg= "Password must contain at least one special character.";    }else if (!numericCharacters.test(password)) {        msg= "Password must contain at least one numeric character.";    }else if (password.length < 8) {        msg= "Password must be at least 8 characters long.";    }       // if (!alphanumericCharacters.test(password)) {    //     msg= "Password must contain at least one alphanumeric character.";    // }    //return "Password is valid.";    if(msg!=''){        $('#'+errid).text(msg);        $('#'+errid).focus();        if(field_id=='frmBasicNewPwd'){        $('#frmBasicConfirmPwd').val('');        $('#frmBasicConfirmPwd').prop( "disabled", true );        $('#ErrfrmBasicConfirmPwd').text("");        }        return false;        }else{             $('#'+errid).text('');             if(field_id=='frmBasicNewPwd'){                 $('#frmBasicConfirmPwd').prop( "disabled", false );             }             return true;        }    }else{       $('#'+errid).text('');     }   }// Example usage// const userPassword = "######1@";// const validationMessage = validatePassword(userPassword);// console.log(validationMessage);    let swalWithBootstrapButtons = Swal.mixin({buttonsStyling: false});        function fnSaveChangePassword() {        $('.form-control').css("border", "1px solid #cccccc");        $('div.herr').text('');        var frmBasicOldPwd		= $("#frmBasicOldPwd").val();        var frmBasicNewPwd			= $("#frmBasicNewPwd").val();        var frmBasicConfirmPwd		= $("#frmBasicConfirmPwd").val();        if(jsTrim(frmBasicOldPwd)== ""){            $('#ErrfrmBasicOldPwd').text("Please fill the old Password");            $('#frmBasicOldPwd').focus();            $('#frmBasicOldPwd').css("border", "1px solid #B94A48");            return false;        }        /*else if(jsTrim(frmBasicOldPwd).length<=5) {            $('#ErrfrmBasicOldPwd').text("Invalid Password!");            $('#frmBasicOldPwd').focus();            $('#frmBasicOldPwd').css("border", "1px solid #B94A48");            return false;        }*/        if(jsTrim(frmBasicNewPwd)== ""){            $('#ErrfrmBasicNewPwd').text("Please fill the New Password");            $('#frmBasicNewPwd').focus();            $('#frmBasicNewPwd').css("border", "1px solid #B94A48");            return false;        }        if(jsTrim(frmBasicNewPwd)!= ""){           validatePasswordForm(frmBasicNewPwd,'ErrfrmBasicNewPwd','frmBasicNewPwd');        }                /*else if(!isPasswordRule(frmBasicNewPwd)) {            $('#ErrfrmBasicNewPwd').text("Invalid Password!");            $('#frmBasicNewPwd').focus();            $('#frmBasicNewPwd').css("border", "1px solid #B94A48");            return false;        }*/        if(jsTrim(frmBasicConfirmPwd)== ""){            $('#ErrfrmBasicConfirmPwd').text("Please fill the confirm Password");            $('#frmBasicConfirmPwd').focus();            $('#frmBasicConfirmPwd').css("border", "1px solid #B94A48");            return false;        }         if(jsTrim(frmBasicConfirmPwd)!= ""){            validatePasswordForm(frmBasicConfirmPwd,'ErrfrmBasicConfirmPwd','frmBasicConfirmPwd');        }        if(jsTrim(frmBasicNewPwd)!=jsTrim(frmBasicConfirmPwd)){            $('#ErrfrmBasicConfirmPwd').text("Password and Confirm Password should be same");            $('#frmBasicConfirmPwd').focus();            $('#frmBasicConfirmPwd').css("border", "1px solid #B94A48");            return false;        }        var Parameters = "rfrom=1&op="+encodeURIComponent(frmBasicOldPwd)+"&np="+encodeURIComponent(frmBasicNewPwd)+"&cp="+encodeURIComponent(frmBasicConfirmPwd);        if(frmBasicOldPwd && frmBasicNewPwd && frmBasicConfirmPwd){            swalWithBootstrapButtons.fire({                                title: 'Do you want to save the details ?',                                type: 'warning',                                showCancelButton: true,                                scrollbarPadding: false,                                confirmButtonText: 'Yes',                                cancelButtonText: 'No',                                reverseButtons: true,                                width:460,                                customClass: {'confirmButton': 'btn btn-green mx-2 px-3',  'cancelButton': 'btn btn-red mx-2 px-3'}}).then(function(result) {    								if (result.value) {                                    MakeAsynPostRequest(base_path+'profile/updatePassword',Parameters,'json',fnChangePasswordRes);                                    return false;     								}                                });        }           }    function fnChangePasswordRes(data) {        if(data!='') {            if(data.errcode == '404') {                fnCallSessionExpire();                return false;            } else if(data.errcode==='-1') {                $('#ErrOldPassword').text(data.msg);                return false;            } else if(data.errcode===1) {                // $('#divSuccessBasicInfoMsg').removeClass('hide');                // $('#divSuccessBasicInfoMsg').text(data.msg);                // fnRedirectPageTimeOut(base_path);                                swalWithBootstrapButtons.fire({                    title: 'Saved!',                    //text: 'Operation Completed Successfully.',                    type: 'success',                    icon: 'success',                    customClass: {'confirmButton': 'btn btn-info'}                }).then((result) => {                fnRedirectPageTimeOut(base_path);                });            }        }    }        function validatePasswordForm(password,errid,field_id) {            // Get the password input            //var password = document.getElementById("password").value;            // Define the regular expressions for validation            var minLength = 8;            var maxLength = 40;            var upperCaseRegex = /[A-Z]/;            var lowerCaseRegex = /[a-z]/;           // var alphaNumericRegex = /^[a-zA-Z0-9]+$/;            var alphabeticCharacters = /[a-zA-Z]+/;  // Check if password contains at least one alphabetic character            var specialCharRegex = /[!@#$%^&*()_+{}\[\]:;<>,.?~\\/-]/;            const numericCharacters = /[0-9]+/; // Check if password contains at least one numeric character                        // Check if the password meets all criteria            if (password.length < minLength || password.length > maxLength) {                alert("Password must be between 8 and 40 characters.");                return false;            }            if (!upperCaseRegex.test(password)) {                alert("Password must contain at least one uppercase letter.");                return false;            }            if (!lowerCaseRegex.test(password)) {                alert("Password must contain at least one lowercase letter.");                return false;            }                        if (!alphabeticCharacters.test(password)) {               alert("Password must contain at least one alphabetic character.");                return false;            }                        if (!numericCharacters.test(password)) {                alert("Password must contain at least one numeric character.");                return false;            }                        // if (!alphaNumericRegex.test(password)) {            //     alert("Password must be alphanumeric.");            //     return false;            // }            if (!specialCharRegex.test(password)) {                alert("Password must contain at least one special character.");                return false;            }                        // If all criteria are met, the form can be submitted           // alert("Password is valid!");            if($("#frmBasicNewPwd").val()!=''){               $('#frmBasicConfirmPwd').prop( "disabled", false );           }            // $('#frmBasicConfirmPwd').prop( "disabled", false );             return true;        }</script><?php $this->load->view(CNFCOMPANY . 'template/pagefooter'); ?>